<?php use App\Services\Auth;use App\Core\DB;if(!Auth::can('media'))return;$isGallery=$module==='gallery_items';$relation=$isGallery?'album_id':'product_id';$table=$isGallery?'gallery_albums':'products';$choices=DB::all('SELECT id,title FROM `'.$table.'` ORDER BY title');if(!$choices)return;?>
<details class="panel related-tools"><summary>↑ Upload multiple images <?=$isGallery?'to an album':'for a product'?></summary><form method="post" enctype="multipart/form-data" action="<?=e(cms_url('/admin/upload'))?>" class="form-grid" style="margin-top:20px"><?=csrf_field()?><label class="field"><?=$isGallery?'Gallery album':'Product'?><select name="<?=$relation?>" required><option value="">Choose <?=$isGallery?'an album':'a product'?></option><?php foreach($choices as $choice):?><option value="<?=$choice['id']?>" <?=(int)(request()->query()[$relation]??0)===(int)$choice['id']?'selected':''?>><?=e($choice['title'])?></option><?php endforeach?></select></label><label class="field">Image files<input type="file" name="files[]" accept="image/jpeg,image/png,image/webp,image/gif" multiple required></label><div class="field wide"><p class="muted"><?=$isGallery?'Each image becomes a draft gallery entry. Add captions and publish it when ready.':'Additional product images are applied immediately to published products.'?></p><button class="button" type="submit">Upload & create entries →</button></div></form></details>
